import java.util.*; public class PedidoDesafio { private final String numero; private String status="ABERTO"; private final List<Double> itens=new ArrayList<>(); public PedidoDesafio(String n){numero=n;} public void adicionar(double v){if(v>0&&status.equals("ABERTO"))itens.add(v);} public double getTotal(){return itens.stream().mapToDouble(Double::doubleValue).sum();} public String getStatus(){return status;} public void pagar(){if(!itens.isEmpty()&&status.equals("ABERTO"))status="PAGO";} public static void main(String[] a){PedidoDesafio p=new PedidoDesafio("P1");p.adicionar(10);p.pagar();System.out.println(p.getStatus()+" "+p.getTotal());}}
